-- 100_seed_banco_questoes_licao_bibliologia_homiletica.sql
-- (Renumerada de 096 para 100 em 12/09/2026 — ver nota no topo de
-- 099_banco_questoes_licao_pool_sorteio.sql sobre o motivo da renumeração.)
--
-- Popula avaliacoes_banco_questoes_licao (criada na migration 099) com
-- os 296 itens verificados item a item contra BIBLIOLOGIA.pdf/HOMILETICA.pdf
-- (Curso Médio) + GABARITO EXERCICIOS.pdf (Bibliologia e Homilética),
-- extraídos em docs/banco_questoes.csv. O item 7.10 de Homilética
-- (questão dissertativa, sem gabarito objetivo) foi excluído do banco
-- de sorteio por decisão do Joaquim em 12/09/2026.
--
-- Estratégia: carrega os dados brutos (mesmas colunas do CSV) numa
-- tabela auxiliar temporária, transforma formato/opções por tipo de
-- questão com SQL (evita erro de transcrição manual de JSON), e depois
-- remove a tabela auxiliar. Aplicada manualmente no staging em
-- 12/09/2026 (ver README de supabase/migrations).

CREATE TABLE public._staging_banco_questoes_raw (
  materia text NOT NULL,
  licao integer NOT NULL,
  item text NOT NULL,
  formato text NOT NULL,
  enunciado text NOT NULL,
  alternativas text,
  resposta_correta text NOT NULL,
  fonte text
);


SELECT
  CASE r.materia
    WHEN 'Bibliologia' THEN (SELECT id FROM public.lessons WHERE title = 'Bibliologia')
    WHEN 'Homilética' THEN (SELECT id FROM public.lessons WHERE title = 'Homilética')
  END AS lesson_id,
  r.licao,
  CASE r.formato
    WHEN 'Certo/Errado' THEN 'CERTO_ERRADO'
    WHEN 'Múltipla escolha' THEN 'MULTIPLA_ESCOLHA'
    WHEN 'Sublinhar (escolha da palavra correta)' THEN 'MULTIPLA_ESCOLHA'
    WHEN 'Preencher lacuna' THEN 'PREENCHER_LACUNA'
    WHEN 'Associação de colunas' THEN 'ASSOCIACAO_COLUNAS'
  END AS formato,
  r.enunciado,
  CASE
    WHEN r.formato IN ('Certo/Errado', 'Preencher lacuna') THEN NULL
    ELSE to_jsonb(string_to_array(r.alternativas, ' | '))
  END AS opcoes,
  r.resposta_correta,
  r.fonte
FROM public._staging_banco_questoes_raw r;

DROP TABLE public._staging_banco_questoes_raw;
